package com.company.skillplatform.audit.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import com.company.skillplatform.skill.infrastructure.entity.SkillEntity;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import jakarta.persistence.*;
@Entity@Table(name="download_log")public class DownloadLogEntity extends BaseJpaEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private IamUserEntity user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="skill_id")private SkillEntity skill;@Column(name="artifact_id")private Long artifactId;@Column(name="bundle_id")private Long bundleId;@Column(name="object_key",nullable=false,length=512)private String objectKey;protected DownloadLogEntity(){}public DownloadLogEntity(IamUserEntity u,SkillEntity s,Long a,Long b,String key){user=u;skill=s;artifactId=a;bundleId=b;objectKey=key;}public SkillEntity getSkill(){return skill;}}
